// CJI-3: may the code unit u, above U+007F, start an identifier (cont 0: \p{ID_Start}) or continue
// one (cont 1: \p{ID_Continue})? 1 or 0, and 0 for ASCII, which the lexer (src/parse.js) tests
// itself. The subset's regular expressions have no \p{...}. Chapter 31's native primitive: rt_id_char in runtime.c answers from the same table
// (runtime/idtable.h; both generated by tools/gen-idtable.mjs).
import { ID_START, ID_CONTINUE } from './idtable.js';

export function $nat_id_char(u /*: Int */, cont /*: Int */) /*: Int */ {
  if (u < 128) return 0;
  const r = cont === 1 ? ID_CONTINUE : ID_START;
  let lo = 0, hi = r.length / 2 - 1;   // binary search over the ranges [r[2k], r[2k + 1]]
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (u < r[2 * mid]) hi = mid - 1;
    else if (u > r[2 * mid + 1]) lo = mid + 1;
    else return 1;
  }
  return 0;
}
